// Improved app.js with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security headers
app.use(helmet());

// Rate limiting - prevent DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later' },
});
app.use('/api', limiter);

// Parse JSON body with size limit (prevents large payload attacks)
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded form data
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Centralized error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: message 
  });
});

// Input sanitization helper
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.replace(/[<>\"'&]/g, ''); // Basic XSS prevention
};

// Validate query parameters for /users
const validateUserParams = (req, res, next) => {
  const { id, limit, offset } = req.query;

  // Validate 'id' if provided
  if (id && (!/^\d+$/.test(id) || parseInt(id) <= 0)) {
    return res.status(400).json({ error: 'Invalid id parameter' });
